class Solution
{
public:
    int n,m;
    //To Solve this problem lets go through in counting the no. of Islands first , how can we do that.
    //Now I will be storing the shape
    void dfs(vector<vector<int>> &grid,vector<vector<int>> &visited,int i,int j,int base_i,int base_j,vector<pair<int,int>>&shape){
        //Condition of Overflow ( Base Case Termination Condition)
        if(i<0||j<0||i>=n||j>=m||visited[i][j]==1||grid[i][j]==0) return;
        //Lets Visit i,j
        visited[i][j]=1;
        shape.push_back({i-base_i,j-base_j});
        //Lets visit all four direction
        dfs(grid,visited,i+1,j,base_i,base_j,shape);
        dfs(grid,visited,i,j+1,base_i,base_j,shape);
        dfs(grid,visited,i-1,j,base_i,base_j,shape);
        dfs(grid,visited,i,j-1,base_i,base_j,shape);
    }
    int countDistinctIslands(vector<vector<int>> &grid){
        n = grid.size();
        m = grid[0].size();
        set<vector<pair<int,int>>> shapes_set;
        vector<vector<int>>visited(n,vector<int>(m,0));
        vector<pair<int,int>>shape;
        for(int i=0;i<n;i++){
            for(int j=0;j<m;j++){
                if(grid[i][j]==1 && !visited[i][j]){
                    shape.clear();
                    dfs(grid,visited,i,j,i,j,shape);
                    shapes_set.insert(shape);
                }
            }
        }
        return shapes_set.size();
    }
};

