```java[]
class Solution {
    private int[] dx = {-1, 0, 1, 0};
    private int[] dy = {0, -1, 0, 1};
    private char[] direction = {'U', 'L', 'D', 'R'};
    private int rows;
    private int cols;

    public int countDistinctIslands(int[][] grid) {
        rows = grid.length;
        cols = grid[0].length;
        Set<String> set = new HashSet<>();
        boolean[][] visited = new boolean[rows][cols];

        for (int i = 0; i < rows; ++i) {
            for (int j = 0; j < cols; ++j) {
                if (!visited[i][j] && grid[i][j] == 1) {
                    StringBuilder sb = new StringBuilder();
                    sb.append("S");
                    dfs(grid, visited, sb, i, j);
                    set.add(sb.toString());
                }
            }
        }
        return set.size();
    }

    private void dfs(int[][] grid, boolean[][] visited, StringBuilder sb, int i, int j) {
        visited[i][j] = true;

        for (int k = 0; k < 4; ++k) {
            int nr = i+dx[k], nc = j+dy[k];

            if (isValid(nr, nc) && !visited[nr][nc] && grid[nr][nc] == 1) {
                sb.append(direction[k]);
                dfs(grid, visited, sb, nr, nc);
            }
        }
        sb.append('B');
    }

    private boolean isValid(int i, int j) {
        return (i >= 0 && i < rows && j >= 0 && j < cols);
    }
}

