## Solution
```java[]
class Solution {
    public int countDistinctIslands(int[][] grid) {
        // Determine the dimensions
        int n = grid.length;
        int m = grid[0].length;

        Set<String> distinctIslands = new HashSet<>();

        // visited  matrix
        boolean[][] visited = new boolean[n][m];

        // Traverse the matrix
        for(int i=0; i < n; i++) {
            for(int j=0; j < m; j++) {
                if(grid[i][j] == 1 && !visited[i][j]){
                    StringBuilder shapeSignature = new StringBuilder();
                    dfsTravel(grid, i, j, visited, shapeSignature, "O"); 
                    distinctIslands.add(shapeSignature.toString());
                }
            }
        }

        return distinctIslands.size();
    }

    public void dfsTravel(int[][] grid, int row, int col, boolean[][] visited,StringBuilder sb, String dir) {
        visited[row][col] = true;

        // Record the direction we took to get here
        sb.append(dir); 

        // Traverse Up
        if(isValid(grid, row - 1, col) && !visited[row - 1][col]) {
            dfsTravel(grid, row - 1, col, visited, sb, "U");
        }

        // Traverse Down
        if(isValid(grid, row + 1, col) && !visited[row + 1][col]) {
            dfsTravel(grid, row + 1, col, visited, sb, "D");
        }

        // Traverse Left
        if(isValid(grid, row, col - 1) && !visited[row][col - 1]) {
            dfsTravel(grid, row, col - 1, visited, sb, "L");
        }

        // Traverse Right
        if(isValid(grid, row, col + 1) && !visited[row][col + 1]) {
            dfsTravel(grid, row, col + 1, visited, sb, "R");
        }

        // Record a "Backtrack" character. 
        sb.append("B");
    }

    public boolean isValid(int[][] grid, int row, int col) {
        // Traverse the 4 neighbors and validate
        if(
            row >= 0 && 
            col >= 0 && 
            row < grid.length && 
            col < grid[row].length &&
            grid[row][col] == 1
        ) {
            return true;
        }
        return false;
    }
}
